 CREATE OR REPLACE FUNCTION public.getintakeda(p_author integer, pagenumber bigint, pagesize bigint)                                                                                                                                                                   
  RETURNS TABLE(id integer, intakenumber character varying, datereceived timestamp without time zone, timereceived timestamp with time zone, narrative text, raname character varying, entityname character varying, cruworkername character varying, isreview boolean)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                     
 AS $function$                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                       
   DECLARE v_Role VARCHAR(50);                                                                                                                                                                                                                                         
   v_Team uuid;                                                                                                                                                                                                                                                        
   v_Region VARCHAR(50);                                                                                                                                                                                                                                               
   v_pageoffset int;                                                                                                                                                                                                                                                   
   v_pagenumber int;                                                                                                                                                                                                                                                   
   v_UserSID character varying;                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                       
 BEGIN                                                                                                                                                                                                                                                                 
         SELECT securityusersid into v_UserSID FROM muser as A where A.id = p_author;                                                                                                                                                                                  
         RAISE NOTICE 'v_UserSID--->%',v_UserSID;                                                                                                                                                                                                                      
         v_pagenumber := pagenumber-1;                                                                                                                                                                                                                                 
         v_pageoffset = v_pagenumber * pagesize;                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                       
   /*SELECT string_agg(ITM.Name,',') into v_Role                                                                                                                                                                                                                       
   FROM SecurityUsers SU                                                                                                                                                                                                                                               
        JOIN AuthorizationsTable AUT ON SU.BinaryValue = AUT.objectSid                                                                                                                                                                                                 
        JOIN ItemsTable ITM ON ITM.ItemId = AUT.ItemId                                                                                                                                                                                                                 
   WHERE  SU.SecurityUsersId = v_UserSID; --FIELD                                                                                                                                                                                                                      
 RAISE NOTICE 'v_Role--->%',v_Role;*/                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                       
   SELECT UPPER(name) into v_Role                                                                                                                                                                                                                                      
   FROM role r                                                                                                                                                                                                                                                         
        JOIN rolemapping rm ON rm.roleid = r.id                                                                                                                                                                                                                        
   WHERE  rm.principalid::int = p_author; --FIELD                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                       
   IF (v_Role = 'CRU' OR v_Role = 'FIELD')                                                                                                                                                                                                                             
   THEN                                                                                                                                                                                                                                                                
   RETURN QUERY                                                                                                                                                                                                                                                        
         SELECT  IDAS.id,                                                                                                                                                                                                                                              
                                 IDAS.IntakeNumber,                                                                                                                                                                                                                    
                 IDAS.DateRecieved,                                                                                                                                                                                                                                    
                 IDAS.TimeRecieved,                                                                                                                                                                                                                                    
                 IDAS.Narrative,                                                                                                                                                                                                                                       
                 IDAS.RAName,                                                                                                                                                                                                                                          
                 IDAS.EntityName,                                                                                                                                                                                                                                      
                 IDAS.CRUWorkerName,                                                                                                                                                                                                                                   
                 false                                                                                                                                                                                                                                                 
         FROM IntakeDAStaging IDAS                                                                                                                                                                                                                                     
         WHERE IDAS.InsertedBy = v_UserSID                                                                                                                                                                                                                             
               AND lower(IDAS.Status) = 'pending'                                                                                                                                                                                                                      
               AND IDAS.Activeflag = 1                                                                                                                                                                                                                                 
         ORDER BY IDAS.InsertedOn DESC LIMIT pageSize OFFSET v_pageoffset;                                                                                                                                                                                             
   ELSEIF (v_Role = 'APCS')                                                                                                                                                                                                                                            
   THEN                                                                                                                                                                                                                                                                
   --APCS                                                                                                                                                                                                                                                              
   RAISE NOTICE '%','22222222222222222222222222222222222222';                                                                                                                                                                                                          
   SELECT tm.TeamId INTO v_Team                                                                                                                                                                                                                                        
   FROM TeamMemberAssignment TMA                                                                                                                                                                                                                                       
   JOIN TeamMember TM ON TMA.TeamMemberId = TM.TeamMemberId                                                                                                                                                                                                            
   WHERE TMA.SecurityUsersId = v_UserSID                                                                                                                                                                                                                               
         AND TMA.ActiveFlag = 1;                                                                                                                                                                                                                                       
 RAISE NOTICE '%','11111111111111111111111111111111111111';                                                                                                                                                                                                            
    RETURN QUERY                                                                                                                                                                                                                                                       
         SELECT  IDAS.id,                                                                                                                                                                                                                                              
                                 IDAS.IntakeNumber,                                                                                                                                                                                                                    
                 IDAS.DateRecieved,                                                                                                                                                                                                                                    
                 IDAS.TimeRecieved,                                                                                                                                                                                                                                    
                 IDAS.Narrative,                                                                                                                                                                                                                                       
                 IDAS.RAName,                                                                                                                                                                                                                                          
                 IDAS.EntityName,                                                                                                                                                                                                                                      
                 IDAS.CRUWorkerName ,                                                                                                                                                                                                                                  
                 false                                                                                                                                                                                                                                                 
         FROM IntakeDAStaging IDAS                                                                                                                                                                                                                                     
         JOIN TeamMemberAssignment TMA ON IDAS.InsertedBy = TMA.SecurityUsersId                                                                                                                                                                                        
                         AND TMA.ActiveFlag = 1                                                                                                                                                                                                                        
                 JOIN TeamMember TM ON TMA.TeamMemberId = TM.TeamMemberId                                                                                                                                                                                              
                         AND TM.ActiveFlag = 1                                                                                                                                                                                                                         
         WHERE TM.TeamId = v_Team                                                                                                                                                                                                                                      
               AND lower(IDAS.Status) = 'pending'                                                                                                                                                                                                                      
               AND IDAS.Activeflag = 1                                                                                                                                                                                                                                 
         ORDER BY IDAS.InsertedOn DESC LIMIT pagesize OFFSET v_pageoffset;                                                                                                                                                                                             
                                                                                                                                                                                                                                                                       
   ELSEIF (v_Role = 'Region_Mgr')                                                                                                                                                                                                                                      
   --Region_Mgr                                                                                                                                                                                                                                                        
   THEN                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                       
   SELECT T.TeamId INTO v_Region                                                                                                                                                                                                                                       
   FROM TeamMemberAssignment TMA                                                                                                                                                                                                                                       
   JOIN TeamMember TM ON TMA.TeamMemberId = TM.TeamMemberId                                                                                                                                                                                                            
   JOIN Team T on TM.TeamId = T.TeamId                                                                                                                                                                                                                                 
   WHERE TMA.SecurityUsersId = v_UserSID                                                                                                                                                                                                                               
         AND TMA.ActiveFlag = 1;                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                       
    RETURN QUERY                                                                                                                                                                                                                                                       
         SELECT  IDAS.id,                                                                                                                                                                                                                                              
                                 IDAS.IntakeNumber,                                                                                                                                                                                                                    
                 IDAS.DateRecieved,                                                                                                                                                                                                                                    
                 IDAS.TimeRecieved,                                                                                                                                                                                                                                    
                 IDAS.Narrative,                                                                                                                                                                                                                                       
                 IDAS.RAName,                                                                                                                                                                                                                                          
                 IDAS.EntityName,                                                                                                                                                                                                                                      
                 IDAS.CRUWorkerName,                                                                                                                                                                                                                                   
                 false                                                                                                                                                                                                                                                 
         FROM IntakeDAStaging IDAS                                                                                                                                                                                                                                     
         JOIN TeamMemberAssignment TMA ON IDAS.InsertedBy = TMA.SecurityUsersId                                                                                                                                                                                        
                         AND TMA.ActiveFlag = 1                                                                                                                                                                                                                        
                 JOIN TeamMember TM ON TMA.TeamMemberId = TM.TeamMemberId                                                                                                                                                                                              
                         AND TM.ActiveFlag = 1                                                                                                                                                                                                                         
                 JOIN Team T on TM.TeamId = T.TeamId                                                                                                                                                                                                                   
         WHERE (T.ParentTeamId = v_Region or t.TeamId = v_Region)                                                                                                                                                                                                      
               AND lower(IDAS.Status) = 'pending'                                                                                                                                                                                                                      
               AND IDAS.Activeflag = 1                                                                                                                                                                                                                                 
         ORDER BY IDAS.InsertedOn DESC LIMIT pageSize OFFSET v_pageoffset;                                                                                                                                                                                             
   ELSE                                                                                                                                                                                                                                                                
   --ALL                                                                                                                                                                                                                                                               
   RETURN QUERY                                                                                                                                                                                                                                                        
     /*   SELECT   IDAS.id,                                                                                                                                                                                                                                            
                                 IDAS.IntakeNumber,                                                                                                                                                                                                                    
                 IDAS.DateRecieved,                                                                                                                                                                                                                                    
                 IDAS.TimeRecieved,                                                                                                                                                                                                                                    
                 IDAS.Narrative,                                                                                                                                                                                                                                       
                 IDAS.RAName,                                                                                                                                                                                                                                          
                                 IDAS.EntityName,                                                                                                                                                                                                                      
                                 IDAS.CRUWorkerName                                                                                                                                                                                                                    
         FROM IntakeDAStaging IDAS                                                                                                                                                                                                                                     
         WHERE   lower(IDAS.Status) = 'pending'                                                                                                                                                                                                                        
         AND IDAS.Activeflag = 1                                                                                                                                                                                                                                       
         ORDER BY IDAS.InsertedOn DESC LIMIT pageSize OFFSET v_pageoffset;  */                                                                                                                                                                                         
                                                                                                                                                                                                                                                                       
          SELECT   IDAS.id,                                                                                                                                                                                                                                            
                                  IDAS.IntakeNumber ,                                                                                                                                                                                                                  
                 IDAS.DateRecieved,                                                                                                                                                                                                                                    
                 IDAS.TimeRecieved,                                                                                                                                                                                                                                    
                 IDAS.Narrative,                                                                                                                                                                                                                                       
                 IDAS.RAName,                                                                                                                                                                                                                                          
                                 IDAS.EntityName,                                                                                                                                                                                                                      
                                 IDAS.CRUWorkerName ,                                                                                                                                                                                                                  
                 coalesce(r.isreviewrequest,false)                                                                                                                                                                                                                     
         FROM IntakeDAStaging IDAS                                                                                                                                                                                                                                     
         LEFT JOIN  routing r ON r.objectid = IDAS.intakenumber                                                                                                                                                                                                        
                         and r.activeflag =1                                                                                                                                                                                                                           
         WHERE   lower(IDAS.Status) = 'pending'                                                                                                                                                                                                                        
         AND IDAS.Activeflag = 1                                                                                                                                                                                                                                       
         AND coalesce( r.tosecurityusersid ,IDAS.InsertedBy)  =v_UserSID                                                                                                                                                                                               
         ORDER BY IDAS.InsertedOn DESC LIMIT pageSize OFFSET v_pageoffset;                                                                                                                                                                                             
   END IF;                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                       
 END;                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                       
 $function$                                                                                                                                                                                                                                                            

